  'rdoc-maint-h': { en:'MAINTENANCE', nl:'ONDERHOUD', es:'MANTENIMIENTO', fr:'ENTRETIEN', de:'INSTANDHALTUNG', pt:'MANUTENÇÃO', it:'MANUTENZIONE', ru:'ОБСЛУЖИВАНИЕ' },
  'rdoc-maint-text': { en:'The Tenant shall maintain the property in good condition. Minor repairs are the responsibility of the Tenant. Structural and major repairs remain the responsibility of the Landlord.', nl:'De huurder dient het gehuurde in goede staat te onderhouden. Klein onderhoud is voor rekening van de huurder. Structureel en groot onderhoud blijft voor rekening van de verhuurder.', es:'El inquilino mantendrá la propiedad en buen estado. Las reparaciones menores son responsabilidad del inquilino. Las reparaciones estructurales y mayores son responsabilidad del propietario.', fr:'Le locataire entretiendra le bien en bon état. Les réparations mineures sont à la charge du locataire. Les réparations structurelles et majeures restent à la charge du bailleur.', de:'Der Mieter hat das Mietobjekt in gutem Zustand zu halten. Kleinreparaturen gehen zu Lasten des Mieters. Strukturelle und größere Reparaturen bleiben Sache des Vermieters.', pt:'O inquilino é responsável pela manutenção regular do imóvel e pequenos reparos. O locador é responsável por reparos estruturais.', it:'Il conduttore è responsabile della manutenzione ordinaria e delle piccole riparazioni. Il locatore è responsabile delle riparazioni strutturali.', ru:'Арендатор отвечает за текущее обслуживание и мелкий ремонт. Арендодатель отвечает за капитальный ремонт.' },
  'rdoc-notice-h': { en:'TERMINATION & NOTICE', nl:'OPZEGGING', es:'TERMINACIÓN Y AVISO', fr:'RÉSILIATION ET PRÉAVIS', de:'KÜNDIGUNG', pt:'PRAZO DE AVISO', it:'PERIODO DI PREAVVISO', ru:'СРОК УВЕДОМЛЕНИЯ' },
  'rdoc-sublet-h': { en:'SUBLETTING', nl:'ONDERVERHUUR', es:'SUBARRIENDO', fr:'SOUS-LOCATION', de:'UNTERVERMIETUNG', pt:'SUBLOCAÇÃO', it:'SUBLOCAZIONE', ru:'СУБАРЕНДА' },
  'rdoc-sublet-text': { en:'The Tenant may not sublet or transfer this lease without prior written consent from the Landlord.', nl:'De huurder mag het gehuurde niet onderverhuren of deze huurovereenkomst overdragen zonder voorafgaande schriftelijke toestemming van de verhuurder.', es:'El inquilino no podrá subarrendar ni ceder este contrato sin el consentimiento previo por escrito del propietario.', fr:'Le locataire ne peut sous-louer ni céder ce bail sans le consentement écrit préalable du bailleur.', de:'Der Mieter darf das Mietobjekt nicht ohne vorherige schriftliche Zustimmung des Vermieters untervermieten oder diesen Vertrag übertragen.', pt:'O inquilino não pode sublocar o imóvel sem o consentimento prévio por escrito do locador.', it:'Il conduttore non può sublocare l\'immobile senza il previo consenso scritto del locatore.', ru:'Арендатор не вправе сдавать объект в субаренду без предварительного письменного согласия арендодателя.' },
  'rdoc-rules-h': { en:'HOUSE RULES', nl:'HUISREGELS', es:'NORMAS DE LA VIVIENDA', fr:'RÈGLEMENT INTÉRIEUR', de:'HAUSORDNUNG', pt:'REGRAS DA CASA', it:'REGOLAMENTO', ru:'ПРАВИЛА ПРОЖИВАНИЯ' },
