  'rdoc-disputes-h': { en:'DISPUTES', nl:'GESCHILLEN', es:'DISPUTAS', fr:'LITIGES', de:'STREITIGKEITEN', pt:'DISPUTAS', it:'CONTROVERSIE', ru:'СПОРЫ' },
  'doc-revoke-h': { en:'REVOCATION', nl:'INTREKKING', es:'REVOCACIÓN', fr:'RÉVOCATION', de:'WIDERRUF', pt:'REVOGAÇÃO', it:'REVOCA', ru:'ОТЗЫВ' },
  'doc-revoke-text': { en:'The Grantor may revoke this Power of Attorney at any time by written notice to the Attorney-in-Fact. The revocation takes effect upon receipt of the notice.', nl:'De volmachtgever kan deze volmacht te allen tijde intrekken door middel van een schriftelijke kennisgeving aan de gevolmachtigde. De intrekking gaat in op het moment van ontvangst van de kennisgeving.', es:'El otorgante puede revocar este poder notarial en cualquier momento mediante notificación escrita al apoderado. La revocación surte efecto a partir de la recepción de la notificación.', fr:'Le mandant peut révoquer cette procuration à tout moment par notification écrite au mandataire. La révocation prend effet dès réception de la notification.', de:'Der Vollmachtgeber kann diese Vollmacht jederzeit durch schriftliche Mitteilung an den Bevollmächtigten widerrufen. Der Widerruf wird mit Zugang der Mitteilung wirksam.', pt:'O outorgante pode revogar esta procuração a qualquer momento mediante notificação por escrito ao procurador.', it:'Il mandante può revocare questa procura in qualsiasi momento mediante comunicazione scritta al procuratore.', ru:'Доверитель может отозвать настоящую доверенность в любое время путём письменного уведомления поверенного.' },
